import{_ as t,o,c as l,a2 as a}from"./chunks/framework.BUwdTBzS.js";const g=JSON.parse('{"title":"按需-验证行为详细规范","description":"验证行为详细规范（编辑工具假性成功兜底、批量重命名陷阱、感知类验证判定与熔断）。编辑/重命名 / 样式动画等目视验证场景时按需加载。","frontmatter":{"title":"按需-验证行为详细规范","description":"验证行为详细规范（编辑工具假性成功兜底、批量重命名陷阱、感知类验证判定与熔断）。编辑/重命名 / 样式动画等目视验证场景时按需加载。"},"headers":[],"relativePath":"rules/按需-验证行为详细规范.md","filePath":"rules/按需-验证行为详细规范.md","lastUpdated":null}'),d={name:"rules/按需-验证行为详细规范.md"};function c(r,e,i,s,p,n){return o(),l("div",null,[...e[0]||(e[0]=[a('<blockquote><p>📄 本页由源文件 <code>rules/按需-验证行为详细规范.mdc</code> 自动投影生成（单一权威源）。请勿直接编辑本页。</p></blockquote><h1 id="按需-验证行为详细规范" tabindex="-1">按需-验证行为详细规范 <a class="header-anchor" href="#按需-验证行为详细规范" aria-label="Permalink to &quot;按需-验证行为详细规范&quot;">​</a></h1><blockquote><p>从 AI 行为规范精简版移出（2026-05-26）。基线规则见 AI 行为规范 §「验证行为规范」。</p></blockquote><h2 id="跨文件交叉引用必须双向闭环-2026-05-15" tabindex="-1">跨文件交叉引用必须双向闭环（2026-05-15） <a class="header-anchor" href="#跨文件交叉引用必须双向闭环-2026-05-15" aria-label="Permalink to &quot;跨文件交叉引用必须双向闭环（2026-05-15）&quot;">​</a></h2><p>设计原则文档 / 规则文档 / 实施沉淀文档之间，引用必须<strong>双向闭环</strong>而非单向。判定标准：对每条新增的「A 文档引用 B 文档」，必须同时检查「B 文档是否引用回 A 文档」；自检命令：在 A、B 双方各自 <code>grep</code> 对方的关键标识符，若任一方为空 → 断链待修。</p><h2 id="编辑工具假性成功兜底-2026-05-19-×4-同形-promote" tabindex="-1">编辑工具假性成功兜底（2026-05-19 ×4 同形 promote） <a class="header-anchor" href="#编辑工具假性成功兜底-2026-05-19-×4-同形-promote" aria-label="Permalink to &quot;编辑工具假性成功兜底（2026-05-19 ×4 同形 promote）&quot;">​</a></h2><p>编辑工具（<code>replace_in_file</code> / <code>multi_replace</code> / <code>edit_file</code>）回报 success 不等于内容真实落盘；<code>grep_search</code> / <code>codebase_search</code> 工具结果存在缓存延迟，不能作为承诺一致性的最终证据。</p><p><strong>同形病灶累积</strong>：</p><ol><li><code>replace_in_file</code> 报 success 但磁盘未变（5/15）</li><li><code>multi_replace</code> 越权重写整个文件（5/19 早）</li><li><code>multi_replace</code> 含中文标点 old_string 偶发匹配失败（5/19 晚）</li><li><code>grep_search</code> 显示零命中但终端 grep 实测全命中（5/19 晚）</li></ol><p><strong>强制范式</strong>：</p><ol><li>关键编辑后立即 <code>grep -c &quot;&lt;新增关键词&gt;&quot; &lt;文件&gt;</code> + <code>wc -l &lt;文件&gt;</code> 双重验证</li><li>工具失败 1 次后立即降级换工具（<code>multi_replace</code> → <code>replace_in_file</code> → <code>edit_file</code> → 终端 <code>printf &gt;&gt; tmp; mv -f</code>），禁止重试同工具同参数</li><li>含中文标点（<code>（）</code>/<code>、</code>/<code>&quot;&quot;</code>/<code>「」</code>）的 old_string 优先用 <code>edit_file</code> 占位符模式</li></ol><h2 id="批量重命名-全局替换三大陷阱-2026-05-21-×5-同形-promote" tabindex="-1">批量重命名/全局替换三大陷阱（2026-05-21 ×5 同形 promote） <a class="header-anchor" href="#批量重命名-全局替换三大陷阱-2026-05-21-×5-同形-promote" aria-label="Permalink to &quot;批量重命名/全局替换三大陷阱（2026-05-21 ×5 同形 promote）&quot;">​</a></h2><p>批量替换/重命名场景中，连环 bash 命令存在三类独立陷阱常导致<strong>假性成功</strong>：</p><h3 id="_1-链式-sed-mv-短路判断" tabindex="-1">① 链式 sed + <code>[[ ]] &amp;&amp; mv</code> 短路判断 <a class="header-anchor" href="#_1-链式-sed-mv-短路判断" aria-label="Permalink to &quot;① 链式 sed + `[[ ]] &amp;&amp; mv` 短路判断&quot;">​</a></h3><p>一行 bash 串多个 sed + grep + 条件判断 + mv 时，终端回显被截断 + 短路链使 mv 静默跳过，但前置 echo &quot;✅&quot; 仍执行 → 误判落盘。</p><p><strong>强制</strong>：改用 <code>sed -i &#39;&#39;</code>（macOS 语法）单文件单行命令。</p><h3 id="_2-grep-c-子串污染" tabindex="-1">② <code>grep -c</code> 子串污染 <a class="header-anchor" href="#_2-grep-c-子串污染" aria-label="Permalink to &quot;② `grep -c` 子串污染&quot;">​</a></h3><p><code>grep -c &quot;issue-trace&quot;</code> 同时匹配 &quot;issues-trace&quot;（子串），<code>DIFF_AFTER</code> 报告值不可靠。</p><p><strong>强制</strong>：只看残留旧名命中数（应为 0），不依赖新名命中数。</p><h3 id="_3-wc-l-终端渲染伪影" tabindex="-1">③ <code>wc -l</code> 终端渲染伪影 <a class="header-anchor" href="#_3-wc-l-终端渲染伪影" aria-label="Permalink to &quot;③ `wc -l` 终端渲染伪影&quot;">​</a></h3><p><code>wc -l &lt; file.txt</code> 报告非 0 数字但 <code>cat</code> 显示空文件，是终端缓冲区残影。</p><p><strong>强制</strong>：用 <code>ls -la</code> 看 size 字节数 + <code>hexdump -C file | head</code> 二进制视图 + <code>file file</code> 三重物理事实兜底。</p><h3 id="sop" tabindex="-1">SOP <a class="header-anchor" href="#sop" aria-label="Permalink to &quot;SOP&quot;">​</a></h3><p>备份 → 双向扫描原始引用点（旧名 + 新名兜底）→ sed -i &#39;&#39; 单文件单行替换 → ls/hexdump 物理验证 → 双向 grep 实测（旧 0 + 新 N）→ 跑回归。</p><h2 id="感知类效果不做自建验证-2026-09-20-事故复盘" tabindex="-1">感知类效果不做自建验证（2026-09-20 事故复盘） <a class="header-anchor" href="#感知类效果不做自建验证-2026-09-20-事故复盘" aria-label="Permalink to &quot;感知类效果不做自建验证（2026-09-20 事故复盘）&quot;">​</a></h2><p><strong>事故</strong>：为确认 Select「面板样式 / 图标切换过渡」两个纯视觉问题，AI 自建「临时入口页 + CDP 驱动无头 Chrome + 动态挂载演示页」完整验证链路，连续 6 轮以上脚本迭代（端口冲突、public 下 HTML 不走 Vite 转换、无头环境路由异常、用例传 show-arrow=false 取不到目标元素……），单轮 30 秒以上，累计数十次工具调用；最终结论仍是「我这边无法复现，需你确认」——与直接询问用户收益相同，成本却高出两个数量级。</p><p><strong>验证分流表</strong>：</p><table tabindex="0"><thead><tr><th style="text-align:left;">验证对象</th><th style="text-align:left;">手段</th><th style="text-align:left;">上限</th></tr></thead><tbody><tr><td style="text-align:left;">编译 / 类型 / 规范</td><td style="text-align:left;">lint、type-check、grep、读代码</td><td style="text-align:left;">不限（廉价）</td></tr><tr><td style="text-align:left;">逻辑行为（DOM 存在性 / 状态机 / 事件）</td><td style="text-align:left;">单测（vitest + test-utils）</td><td style="text-align:left;">一轮；失败即改断言，不加设施</td></tr><tr><td style="text-align:left;">样式 / 动画 / 布局 / 视觉 / 手感</td><td style="text-align:left;">不做自建验证：说明预期 + 交用户目视</td><td style="text-align:left;">0</td></tr></tbody></table><p><strong>熔断阈值（硬）</strong>：</p><ol><li>同一验证目标连续失败 2 次 → 停止，立即降级</li><li>为验证同一问题新增验证设施达 3 次工具调用仍无结论 → 停止</li><li>需要「起浏览器 / 起额外 dev server / 造临时入口页」级设施时，先自问：能否直接让用户看？能则不发车</li></ol><p><strong>交付话术模板</strong>：</p><blockquote><p>该效果属目视验证项，我无法自证。预期表现：{具体现象}。请你在 {页面} 按 {步骤} 确认，不符请反馈 {截图 / 描述}。</p></blockquote><p><strong>临时文件纪律</strong>：验证用临时文件（入口页 / 脚本 / 测试桩）统一放 /tmp/，禁止落在用户工作区；确需落在工作区时，任务收尾必须立刻删除（2026-09-20 事故中曾在项目根、tests/、public/ 散落 4 个临时文件）。</p>',33)])])}const u=t(d,[["render",c]]);export{g as __pageData,u as default};
